class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        int count = 0;
        int flipPrev2 = 0;
        int flipPrev1 = 0;

        for (int i = 0; i < n; i++) {
            int current = nums[i] ^ flipPrev2 ^ flipPrev1;
            if (current == 0) {
                if (i > n - 3) return -1;
                count++;
                flipPrev2 = flipPrev1;
                flipPrev1 = 1;
            } else {
                flipPrev2 = flipPrev1;
                flipPrev1 = 0;
            }
        }
        return count;
    }
};
